// Shared server setup: the catalog (generated at deploy time from the
// original game data, never committed) and save migrations.
import { Catalog } from "./rules/catalog.ts";
import type { Dict } from "./rules/catalog.ts";
import { CURRENT_SAVE_VERSION } from "./rules/logic.ts";
// Generated by tools/build_server_data.py (gitignored).
import { ART_CAR_IDS, DATA, TUNING } from "./catalog/data.ts";

let cached: Catalog | null = null;

export function catalog(): Catalog {
  if (cached === null) {
    cached = Catalog.fromData(DATA, TUNING);
    for (const id of ART_CAR_IDS) cached.artCarIds.add(id);
  }
  return cached;
}

/** Server copy of scripts/save/save_migrations.gd. Returns null if unusable. */
export function migrate(save: Dict): Dict | null {
  if (typeof save.save_version !== "number" || save.save_version > CURRENT_SAVE_VERSION) return null;
  const version: number = save.save_version;
  let out = structuredClone(save);
  for (let v = version; v < CURRENT_SAVE_VERSION; v++) {
    // Same steps, in the same order, as SaveMigrations._step().
    if (v === 1) out = v1ToV2(out);
    else if (v === 2) out = v2ToV3(out);
    else return null;
    out.save_version = v + 1;
  }
  return out;
}

/** v3 added parts storage: parts taken off a car, to put back on for free. */
function v2ToV3(save: Dict): Dict {
  save.part_storage = {};
  return save;
}

/** v2 added car tasks (jobs your own car goes out on). */
function v1ToV2(save: Dict): Dict {
  save.car_tasks = {};
  for (const car of save.cars ?? []) {
    car.upgrades = [Math.trunc(car.upgrade ?? 0), 0, 0, 0];
    delete car.upgrade;
  }
  return save;
}
